-- ============================================================================
--  ZUUUM FIBRA · CARGA DEL PADRÓN  ·  parte 1 de 2: los datos
--  1,102 clientes desde `www PAGOS.xlsx`
-- ----------------------------------------------------------------------------
--  Pega TODO este archivo en el SQL Editor y dale Run.
--  Después pega CARGA_2_PROCESAR.sql, que es el que arma clientes y cobranza.
--
--  Esto solo llena una tabla de paso. Todavía no toca nada del sistema.
-- ============================================================================

do $$
begin
  if to_regclass('public.customers') is null then
    raise exception using message =
      E'Todavía no existe el esquema.\n  Corre primero ESQUEMA_COMPLETO.sql.';
  end if;
  if exists (select 1 from public.customers limit 1) then
    raise exception using message =
      E'Esta base ya tiene clientes.\n'
      '  Si quieres volver a cargar, primero hay que decidir qué pasa con los que ya están.';
  end if;
end $$;

drop table if exists public.zuuum_carga;

create table public.zuuum_carga (
  n       bigint generated always as identity primary key,
  zc      text,      -- código de zona: CUE, VEL, PAS…
  nombre  text,
  precio  numeric,
  ip      text,
  idext   text,
  meses   text       -- "202510:1,202511:0"  →  añomes : 1 pagó / 0 no pagó
);

-- Tabla de paso: se borra sola al final de la parte 2.
alter table public.zuuum_carga enable row level security;











-- Comprobación rápida: deben ser 1102 renglones.
select count(*) as renglones_cargados,
       count(*) filter (where precio > 0) as con_precio,
       count(*) filter (where precio is null or precio <= 0) as sin_precio
  from public.zuuum_carga;
